"use client";

import {
  Children,
  forwardRef,
  isValidElement,
  useRef,
  useEffect,
  useState,
  useCallback,
  useMemo,
  createContext,
  useContext,
  type ReactNode,
  type HTMLAttributes,
} from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { Select as SelectPrimitive } from "@base-ui/react/select";
import type { IconComponent } from "@/lib/icon-context";
import { cn } from "@/lib/utils";
import { useProximityHover, type ItemRect } from "@/hooks/use-proximity-hover";
import { useShape } from "@/lib/shape-context";
import { SizeProvider, useSize, type SizeVariant } from "@/lib/size-context";
import { Elevated } from "@/lib/elevated";

// ---------------------------------------------------------------------------
// Overlay rect tracking — shared by the selected/hover/focus highlight divs
// in SelectContent.
//
// Each highlight is a permanently mounted div whose position is driven by a
// measured rect that can go null (nothing hovered/checked/focused). Freezing
// the last rect lets the div fade out in place instead of collapsing to
// (0,0), and `justAppeared` flags the one render where a rect goes from null
// to non-null so the caller can suppress the transition on that update —
// the CSS equivalent of framer-motion's `initial={false}` snap-in-place.
// ---------------------------------------------------------------------------

function useOverlayRect(rect: ItemRect | null) {
  const lastRectRef = useRef<ItemRect | null>(null);
  if (rect) lastRectRef.current = rect;
  const isVisible = rect != null;
  const wasVisibleRef = useRef(isVisible);
  const justAppeared = isVisible && !wasVisibleRef.current;
  useEffect(() => {
    wasVisibleRef.current = isVisible;
  });
  return { rect: lastRectRef.current, isVisible, justAppeared };
}

// ---------------------------------------------------------------------------
// Select context
//
// Built on Base UI's Select primitive, which owns positioning (collision
// flipping, anchor tracking), dismissal (outside press, focus-out, Escape
// nesting inside dialogs), list keyboard navigation + typeahead, combobox
// ARIA, and the hidden form input. This layer keeps the
// proximity-hover overlays, the open/close slide, and the animated checkmark.
// ---------------------------------------------------------------------------

// How long a selection holds the popup open before closing, so the
// acknowledgment — the checkmark drawing in and the selected background
// springing to the picked row — is visible instead of being cut off by the
// ~60ms close fade. Escape and outside presses still close immediately.
const selectionAckMs = 300;

interface SelectContextValue {
  value: string;
  open: boolean;
}

const SelectContext = createContext<SelectContextValue | null>(null);

function useSelectContext() {
  const ctx = useContext(SelectContext);
  if (!ctx) throw new Error("Select compound components must be inside <Select>");
  return ctx;
}

// Content context for proximity hover
interface SelectContentContextValue {
  registerItem: (index: number, element: HTMLElement | null) => void;
  activeIndex: number | null;
  checkedIndex?: number;
}

const SelectContentContext =
  createContext<SelectContentContextValue | null>(null);

// ---------------------------------------------------------------------------
// Select (root)
// ---------------------------------------------------------------------------

interface SelectProps {
  children: ReactNode;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  disabled?: boolean;
  name?: string;
  required?: boolean;
  /** Pins trigger and popup to one step of the size ladder (default 36px,
   *  compact 28px — see the size ladder in globals.css). Omitted, both follow the surrounding
   *  SizeProvider. */
  size?: SizeVariant;
}

/**
 * Walk the children tree collecting `{ value, label }` pairs from SelectItem
 * elements. Passed to Base UI's `items` prop so the trigger can resolve the
 * label of an initial value before the popup has ever mounted (items only
 * render while open). Non-string labels fall back to the raw value, matching
 * the previous labelMap behaviour.
 */
function collectSelectItems(
  node: ReactNode,
  out: { value: string; label: ReactNode }[] = []
) {
  Children.forEach(node, (child) => {
    if (!isValidElement(child)) return;
    const props = child.props as { value?: unknown; children?: ReactNode };
    if (typeof props.value === "string") {
      out.push({
        value: props.value,
        label:
          typeof props.children === "string" ? props.children : props.value,
      });
    } else if (props.children) {
      collectSelectItems(props.children, out);
    }
  });
  return out;
}

function Select({
  children,
  value,
  defaultValue,
  onValueChange,
  disabled = false,
  name,
  required,
  size,
}: SelectProps) {
  const [internalValue, setInternalValue] = useState(defaultValue ?? "");
  const [open, setOpen] = useState(false);
  const currentValue = value !== undefined ? value : internalValue;

  const items = useMemo(() => collectSelectItems(children), [children]);

  const handleValueChange = useCallback(
    (next: string | null) => {
      const v = next ?? "";
      if (value === undefined) setInternalValue(v);
      onValueChange?.(v);
    },
    [value, onValueChange]
  );

  const ackTimeoutRef = useRef<number | null>(null);
  const cancelAckClose = useCallback(() => {
    if (ackTimeoutRef.current !== null) {
      clearTimeout(ackTimeoutRef.current);
      ackTimeoutRef.current = null;
    }
  }, []);
  useEffect(() => cancelAckClose, [cancelAckClose]);

  // Picking an item acknowledges before closing: the close is deferred by
  // selectionAckMs so the checkmark draw and the selected background's spring
  // to the picked row are seen. Every other close reason (Escape, outside
  // press, trigger toggle, focus-out) closes immediately and cancels any
  // pending acknowledgment; re-picking within the window restarts it.
  const handleOpenChange = useCallback(
    (nextOpen: boolean, eventDetails: { reason: string }) => {
      if (!nextOpen && eventDetails.reason === "item-press") {
        cancelAckClose();
        ackTimeoutRef.current = window.setTimeout(() => {
          ackTimeoutRef.current = null;
          setOpen(false);
        }, selectionAckMs);
        return;
      }
      cancelAckClose();
      setOpen(nextOpen);
    },
    [cancelAckClose]
  );

  const ctx = useMemo(
    () => ({ value: currentValue, open }),
    [currentValue, open]
  );

  // A size prop pins the whole compound (trigger + portalled popup — React
  // context crosses portals) to one step of the ladder.
  const root = (
    <SelectContext.Provider value={ctx}>
      <SelectPrimitive.Root
        // Always controlled; "" (no selection) maps to Base UI's null.
        value={currentValue === "" ? null : currentValue}
        onValueChange={handleValueChange}
        open={open}
        onOpenChange={handleOpenChange}
        items={items}
        disabled={disabled}
        name={name}
        required={required}
        // Non-modal: the page keeps scrolling and the Positioner tracks the
        // anchor, so the popup follows its trigger instead of detaching.
        modal={false}
      >
        {children}
      </SelectPrimitive.Root>
    </SelectContext.Provider>
  );

  return size ? <SizeProvider size={size}>{root}</SizeProvider> : root;
}

Select.displayName = "Select";

// ---------------------------------------------------------------------------
// SelectTrigger
// ---------------------------------------------------------------------------

const triggerVariants = cva(
  [
    "group inline-flex items-center justify-between outline-none cursor-pointer",
    "transition-all duration-80",
    "disabled:opacity-50 disabled:pointer-events-none",
    "focus-visible:ring-1 focus-visible:ring-[color:var(--focus-ring,#6B97FF)]",
  ],
  {
    variants: {
      variant: {
        bordered:
          "border border-border bg-transparent text-foreground hover:bg-hover",
        borderless:
          "border border-transparent bg-transparent text-foreground hover:bg-hover",
      },
    },
    defaultVariants: {
      variant: "bordered",
    },
  }
);

interface SelectTriggerProps
  extends Omit<HTMLAttributes<HTMLButtonElement>, "children">,
    VariantProps<typeof triggerVariants> {
  icon?: IconComponent;
  placeholder?: string;
  error?: string;
  /** Size override for the trigger alone. Prefer the `size` prop on <Select>
   *  (or a surrounding SizeProvider) so the popup matches. */
  size?: SizeVariant;
}

const SelectTrigger = forwardRef<HTMLButtonElement, SelectTriggerProps>(
  (
    {
      className,
      variant,
      icon: Icon,
      placeholder = "Select…",
      error,
      size,
      ...props
    },
    ref
  ) => {
    const shape = useShape();
    const sizeClasses = useSize(size);
    const compact = sizeClasses.variant === "compact";

    return (
      <div className="flex flex-col gap-1">
        <SelectPrimitive.Trigger
          ref={ref}
          aria-invalid={!!error || undefined}
          className={cn(
            triggerVariants({ variant }),
            sizeClasses.control,
            sizeClasses.text,
            sizeClasses.px,
            sizeClasses.gap,
            compact ? "min-w-[128px]" : "min-w-[160px]",
            shape.input,
            error && "border-destructive/50 hover:border-destructive/50",
            className
          )}
          {...props}
        >
          <span className={cn("flex items-center min-w-0 flex-1", sizeClasses.gap)}>
            {Icon && (
              <Icon
                size={sizeClasses.icon}
                strokeWidth={1.5}
                className="shrink-0 text-muted-foreground transition-[color,stroke-width] duration-80 group-hover:text-foreground group-hover:stroke-[2]"
              />
            )}
            <SelectPrimitive.Value
              placeholder={placeholder}
              // py-1/-my-1: truncate's overflow:hidden clips at the padding
              // box, and the trimmed box excludes ascenders/descenders — the
              // padding gives glyphs room while the negative margin keeps the
              // trimmed layout box.
              className="min-w-0 flex-1 text-left truncate [text-box:trim-both_cap_alphabetic] py-1 -my-1 data-[placeholder]:text-muted-foreground"
            />
          </span>

          <svg
            width={sizeClasses.icon}
            height={sizeClasses.icon}
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth={2}
            strokeLinecap="round"
            strokeLinejoin="round"
            className="shrink-0 text-muted-foreground transition-colors duration-80 group-hover:text-foreground"
          >
            <path d="M6 9l6 6 6-6" />
          </svg>
        </SelectPrimitive.Trigger>
        {error && (
          <span className="text-[12px] text-destructive pl-3">{error}</span>
        )}
      </div>
    );
  }
);

SelectTrigger.displayName = "SelectTrigger";

// ---------------------------------------------------------------------------
// SelectContent
// ---------------------------------------------------------------------------

interface SelectContentProps {
  className?: string;
  children: ReactNode;
}

const SelectContent = forwardRef<HTMLDivElement, SelectContentProps>(
  ({ className, children }, ref) => {
    const { open, value } = useSelectContext();
    const shape = useShape();
    const containerRef = useRef<HTMLDivElement>(null);

    const {
      activeIndex,
      setActiveIndex,
      itemRects,
      isMeasured,
      handlers,
      registerItem,
      remeasure,
    } = useProximityHover(containerRef);

    const [focusedIndex, setFocusedIndex] = useState<number | null>(null);
    const [checkedIndex, setCheckedIndex] = useState<number | undefined>(
      undefined
    );

    // Fresh rects once per open. Measuring is the hook's job — it owns the
    // one coalesced pass that item registration and container resizes both
    // feed into, and a second pass from elsewhere is what used to land a
    // corrected rect on an already-mounted overlay. The popup keeps its items
    // registered while it sits hidden between opens, so registration alone
    // would never trigger a fresh pass on reopen.
    useEffect(() => {
      if (!open) return;
      remeasure();
    }, [open, remeasure]);

    // Detect the checked row. Deliberately does NOT remeasure on a value
    // change while open: the rows haven't moved, so the published rects stay
    // trustworthy and only checkedIndex switches — which lets the selected
    // marker spring from the old row to the picked one (the selection
    // acknowledgment) instead of unmounting and snapping.
    useEffect(() => {
      if (!open) return;
      // Double rAF: first waits for React commit, second for layout
      let inner: number;
      const outer = requestAnimationFrame(() => {
        inner = requestAnimationFrame(() => {
          const container = containerRef.current;
          if (container) {
            const items = Array.from(
              container.querySelectorAll("[data-proximity-index]")
            ) as HTMLElement[];
            const idx = items.findIndex(
              (el) => el.getAttribute("data-value") === value
            );
            setCheckedIndex(idx !== -1 ? idx : undefined);
          }
        });
      });
      return () => {
        cancelAnimationFrame(outer);
        cancelAnimationFrame(inner);
      };
    }, [open, value]);

    // Reset every overlay index as the close begins. checkedIndex otherwise
    // lags one open behind value (picking an item closes the popup before the
    // effect above re-syncs it), and a leftover activeIndex is worse: Base UI
    // keeps the popup mounted through the exit tween, so on reopen the hover
    // pill would still be sitting on the previously active row and spring from
    // there to the row that auto-focus lands on.
    useEffect(() => {
      if (open) return;
      setCheckedIndex(undefined);
      setActiveIndex(null);
      setFocusedIndex(null);
    }, [open, setActiveIndex]);

    // Overlays read rects only once the hook reports the item set fully
    // measured. Positioning one from an incomplete pass mounts it at the wrong
    // row, and the correcting pass then springs it across the list.
    const activeRect =
      isMeasured && activeIndex !== null ? itemRects[activeIndex] : null;
    const checkedRect =
      isMeasured && checkedIndex != null ? itemRects[checkedIndex] : null;
    const focusRect =
      isMeasured && focusedIndex !== null ? itemRects[focusedIndex] : null;
    const checkedOverlay = useOverlayRect(checkedRect);
    const hoverOverlay = useOverlayRect(activeRect);
    const focusOverlay = useOverlayRect(focusRect);

    const contentCtx = useMemo(
      () => ({ registerItem, activeIndex, checkedIndex }),
      [registerItem, activeIndex, checkedIndex]
    );

    return (
      <SelectPrimitive.Portal>
        <SelectPrimitive.Positioner
          side="bottom"
          align="start"
          sideOffset={6}
          alignItemWithTrigger={false}
          className="z-50 outline-none"
        >
          <SelectContentContext.Provider value={contentCtx}>
            <SelectPrimitive.Popup
              render={
                <Elevated
                  offset={2}
                  shadowLevel={3}
                  ref={(node: HTMLDivElement | null) => {
                    (
                      containerRef as React.MutableRefObject<HTMLDivElement | null>
                    ).current = node;
                    if (typeof ref === "function") ref(node);
                    else if (ref)
                      (
                        ref as React.MutableRefObject<HTMLDivElement | null>
                      ).current = node;
                  }}
                />
              }
              onMouseEnter={() => {
                handlers.onMouseEnter();
                setFocusedIndex(null);
              }}
              onMouseMove={handlers.onMouseMove}
              onMouseLeave={handlers.onMouseLeave}
              onFocus={(e) => {
                const indexAttr = (e.target as HTMLElement)
                  .closest("[data-proximity-index]")
                  ?.getAttribute("data-proximity-index");
                if (indexAttr != null) {
                  const idx = Number(indexAttr);
                  setActiveIndex(idx);
                  setFocusedIndex(
                    (e.target as HTMLElement).matches(":focus-visible")
                      ? idx
                      : null
                  );
                }
              }}
              onBlur={(e) => {
                if (containerRef.current?.contains(e.relatedTarget as Node))
                  return;
                setFocusedIndex(null);
                setActiveIndex(null);
              }}
              className={cn(
                // min-w tracks the trigger via the Positioner's --anchor-width
                // var, matching the pre-migration minWidth: triggerRect.width.
                `relative flex flex-col gap-0.5 min-w-[var(--anchor-width)] max-h-[min(300px,var(--available-height))] overflow-y-auto ${shape.container} p-1 select-none outline-none`,
                "origin-(--transform-origin) transition-[opacity,transform] duration-(--motion-fast) ease-spring",
                "data-[instant]:duration-0",
                "data-[starting-style]:opacity-0 data-[starting-style]:scale-y-95 data-[starting-style]:-translate-y-1",
                "data-[ending-style]:opacity-0 data-[ending-style]:scale-y-95 data-[ending-style]:-translate-y-1",
                "data-[ending-style]:duration-(--motion-fast-exit)",
                className
              )}
            >
              {/* Selected background */}
              <div
                className={cn(
                  `absolute ${shape.bg} bg-active pointer-events-none`,
                  "opacity-0 transition-[top,left,width,height,opacity] duration-(--motion-moderate-exit) ease-spring",
                  checkedOverlay.isVisible && "opacity-100 duration-(--motion-moderate)"
                )}
                style={{
                  ...(checkedOverlay.rect && {
                    top: checkedOverlay.rect.top,
                    left: checkedOverlay.rect.left,
                    width: checkedOverlay.rect.width,
                    height: checkedOverlay.rect.height,
                  }),
                  transitionProperty: checkedOverlay.justAppeared ? "none" : undefined,
                }}
              />

              {/* Hover background */}
              <div
                className={cn(
                  `absolute ${shape.bg} bg-hover pointer-events-none`,
                  "opacity-0 transition-[top,left,width,height,opacity] duration-(--motion-fast-exit) ease-spring",
                  hoverOverlay.isVisible && "opacity-100 duration-(--motion-fast)"
                )}
                style={{
                  ...(hoverOverlay.rect && {
                    top: hoverOverlay.rect.top,
                    left: hoverOverlay.rect.left,
                    width: hoverOverlay.rect.width,
                    height: hoverOverlay.rect.height,
                  }),
                  transitionProperty: hoverOverlay.justAppeared ? "opacity" : undefined,
                }}
              />

              {/* Focus ring */}
              <div
                className={cn(
                  `absolute ${shape.focusRing} pointer-events-none z-20 border border-[color:var(--focus-ring,#6B97FF)]`,
                  "opacity-0 transition-[top,left,width,height,opacity] duration-(--motion-fast-exit) ease-spring",
                  focusOverlay.isVisible && "opacity-100 duration-(--motion-fast)"
                )}
                style={{
                  ...(focusOverlay.rect && {
                    left: focusOverlay.rect.left - 2,
                    top: focusOverlay.rect.top - 2,
                    width: focusOverlay.rect.width + 4,
                    height: focusOverlay.rect.height + 4,
                  }),
                  transitionProperty: focusOverlay.justAppeared ? "none" : undefined,
                }}
              />

              {children}
            </SelectPrimitive.Popup>
          </SelectContentContext.Provider>
        </SelectPrimitive.Positioner>
      </SelectPrimitive.Portal>
    );
  }
);

SelectContent.displayName = "SelectContent";

// ---------------------------------------------------------------------------
// SelectItem
// ---------------------------------------------------------------------------

interface SelectItemProps extends HTMLAttributes<HTMLDivElement> {
  icon?: IconComponent;
  index: number;
  value: string;
  disabled?: boolean;
}

const SelectItem = forwardRef<HTMLDivElement, SelectItemProps>(
  (
    {
      className,
      children,
      icon: Icon,
      value,
      index,
      disabled = false,
      ...props
    },
    ref
  ) => {
    const selectCtx = useSelectContext();
    const contentCtx = useContext(SelectContentContext);
    const internalRef = useRef<HTMLDivElement>(null);
    const shape = useShape();
    const sizeClasses = useSize();
    const compact = sizeClasses.variant === "compact";
    const hasMounted = useRef(false);

    useEffect(() => {
      hasMounted.current = true;
    }, []);

    // Register with proximity hover. Depends on the (stable) registerItem
    // rather than the content context, which is rebuilt on every activeIndex
    // change: keying the effect to the whole context re-ran it per mousemove,
    // unregistering and re-registering every row and so keeping the hook's
    // measurement permanently unsettled while the pointer moved.
    const registerItem = contentCtx?.registerItem;
    useEffect(() => {
      if (!registerItem) return;
      registerItem(index, internalRef.current);
      return () => registerItem(index, null);
    }, [index, registerItem]);

    const isActive = contentCtx?.activeIndex === index;
    const isChecked = selectCtx.value === value;
    const skipAnimation = !hasMounted.current;

    return (
      <SelectPrimitive.Item
        value={value}
        disabled={disabled}
        label={typeof children === "string" ? children : undefined}
        render={
          <div
            ref={(node: HTMLDivElement | null) => {
              (
                internalRef as React.MutableRefObject<HTMLDivElement | null>
              ).current = node;
              if (typeof ref === "function") ref(node);
              else if (ref)
                (ref as React.MutableRefObject<HTMLDivElement | null>).current =
                  node;
            }}
            data-proximity-index={index}
            data-value={value}
            className={cn(
              // Fixed height (was py-2 around a 19.5px line box ≈ 35.5px) so
              // the text-box trim on the item text doesn't shrink the row.
              // shrink-0: the popup is a max-height flex column, so without it
              // a long list compresses rows to fit instead of scrolling.
              `relative z-10 flex ${sizeClasses.control} shrink-0 items-center ${sizeClasses.gap} ${shape.item} ${sizeClasses.itemPx} ${sizeClasses.text} cursor-pointer outline-none select-none`,
              "transition-[color] duration-80",
              isActive || isChecked
                ? "text-foreground"
                : "text-muted-foreground",
              disabled && "opacity-50 pointer-events-none",
              className
            )}
            {...props}
          />
        }
      >
        {Icon && (
          <Icon
            size={sizeClasses.icon}
            strokeWidth={isActive || isChecked ? 2 : 1.5}
            className="shrink-0 transition-[color,stroke-width] duration-80"
          />
        )}

        <SelectPrimitive.ItemText
          // py-1/-my-1 keeps truncate's overflow:hidden from clipping
          // ascenders/descenders outside the trimmed box.
          render={<span className="flex-1 min-w-0 truncate [text-box:trim-both_cap_alphabetic] py-1 -my-1" />}
        >
          {children}
        </SelectPrimitive.ItemText>

        {/* Always-rendered fixed slot so the check appearing/disappearing
            never changes the row's intrinsic width — without it the whole
            popup resizes when a selection lands. The check itself is also
            always rendered: pathLength="100" normalizes the path to 100
            units, so a plain stroke-dashoffset transition draws it in
            (100 → 0) and undraws it (0 → 100) as `isChecked` flips. */}
        <span
          aria-hidden
          className={cn("shrink-0", compact ? "w-3.5 h-3.5" : "w-4 h-4")}
        >
          <svg
            width={sizeClasses.icon}
            height={sizeClasses.icon}
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth={2}
            strokeLinecap="round"
            strokeLinejoin="round"
            className={cn(
              "text-foreground",
              isChecked ? "opacity-100" : "opacity-0"
            )}
          >
            <path
              d="M4 12L9 17L20 6"
              pathLength="100"
              className={cn(
                "transition-[stroke-dashoffset] ease-spring duration-(--motion-fast)",
                // No tier matches this 40ms exit — bespoke duration, same as
                // the radio tick's exit (see motion-guidelines.md).
                !isChecked && "duration-[40ms]",
                skipAnimation && "transition-none"
              )}
              style={{
                strokeDasharray: 100,
                strokeDashoffset: isChecked ? 0 : 100,
              }}
            />
          </svg>
        </span>
      </SelectPrimitive.Item>
    );
  }
);

SelectItem.displayName = "SelectItem";

// ---------------------------------------------------------------------------
// SelectGroup + SelectLabel + SelectSeparator
// ---------------------------------------------------------------------------

function SelectGroup({
  children,
  className,
  ...props
}: HTMLAttributes<HTMLDivElement>) {
  return (
    <div role="group" className={className} {...props}>
      {children}
    </div>
  );
}

SelectGroup.displayName = "SelectGroup";

const SelectLabel = forwardRef<HTMLDivElement, HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => {
    // Group labels are the caption role of the type scale — see the size ladder in globals.css.
    const compact = useSize().variant === "compact";
    return (
      <div
        ref={ref}
        className={cn(
          "px-2 py-1.5 shrink-0 text-muted-foreground",
          compact ? "text-[11px]" : "text-[12px]",
          className
        )}
        {...props}
      />
    );
  }
);

SelectLabel.displayName = "SelectLabel";

const SelectSeparator = forwardRef<
  HTMLDivElement,
  HTMLAttributes<HTMLDivElement>
>(({ className, ...props }, ref) => (
  <div
    ref={ref}
    role="separator"
    className={cn("my-1 -mx-1 h-px shrink-0 bg-border/60", className)}
    {...props}
  />
));

SelectSeparator.displayName = "SelectSeparator";

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

export {
  Select,
  SelectTrigger,
  SelectContent,
  SelectItem,
  SelectGroup,
  SelectLabel,
  SelectSeparator,
  triggerVariants,
};

export type { SelectProps, SelectTriggerProps, SelectContentProps, SelectItemProps };
